const sub = (a, b) => ({ x: a.x - b.x, y: a.y - b.y });  // b → a 로 가는 화살표
const add = (a, b) => ({ x: a.x + b.x, y: a.y + b.y });  // 이동을 이어 붙임
const scale = (v, s) => ({ x: v.x * s, y: v.y * s });    // 크기 조절(속도×시간)
const len = (v) => Math.hypot(v.x, v.y);                 // √(x²+y²) — 크기
const norm = (v) => { const l = len(v); return { x: v.x/l, y: v.y/l }; }; // 길이 1(방향만)
// 위치·이동·방향을 좌표 하나하나가 아니라 화살표로 → 코드가 간결

// ❌ 매 프레임 수천 번 sqrt (느림)
if (len(sub(a, b)) < 100) …

// ✅ 제곱끼리 비교 (대소 관계는 같다 — sqrt 없이)
const dist2 = (a, b) => { const dx=a.x-b.x, dy=a.y-b.y; return dx*dx+dy*dy; };
if (dist2(a, b) < 100*100) …

// ⚠ 정규화 전에 길이 0 확인 — 0으로 나눈 NaN 이 위치에 섞이면 사라짐
const norm = (v) => {
  const l = len(v);
  return l === 0 ? { x: 1, y: 0 } : { x: v.x/l, y: v.y/l };  // 가드
};

const cross = (a, b) => a.x * b.y - a.y * b.x;   // 2D 는 숫자 하나

// cross > 0  왼쪽(반시계)
// cross < 0  오른쪽(시계)
// cross = 0  일직선(평행)

// 내적 = 앞뒤, 외적 = 좌우 (둘이 짝)
// |cross| = 평행사변형 넓이 = |a||b|sin(각도)
// 삼각형 넓이 = |cross(b-a, c-a)| / 2
// 활용: 좌/우회전·점이 선의 어느 쪽·감김 방향·볼록 껍질

// ❌ 프레임마다 그냥 더함 — 120Hz 에서 두 배 빨라짐
pos.x += speed.x;

// ✅ 항상 dt(경과 시간)를 곱한다 — 프레임률과 무관
let last = performance.now();
function frame(now) {
  const dt = (now - last) / 1000;   // 초 단위 경과 시간
  last = now;
  const clampedDt = Math.min(dt, 0.05);   // dt 상한(랙·탭 복귀 시 튐 방지)
  pos.x += speed.x * clampedDt;
  pos.y += speed.y * clampedDt;
  requestAnimationFrame(frame);
}
// 물리·이동·타이머는 프레임 수가 아니라 시간(dt) 기준으로
